# --- резервы ------------------------------------------------------------

def reserve(
    self,
    order_id: str,
    lines: Iterable[tuple[str, str, int] | ReservationLine],
    ttl: timedelta | None = None,
) -> Reservation:
    """Удерживает товар под заказ сразу по всем строкам (всё или ничего)."""
    _validate_code(order_id, "order_id")
    ttl = DEFAULT_RESERVATION_TTL if ttl is None else check_ttl(ttl)
    normalized = normalize_lines(lines)
    for line in normalized:
        self._check_position(line.warehouse, line.sku)
        _validate_qty(line.qty)
    if not normalized:
        raise ValidationError("reservation must have at least one line")
    now = self._clock.now()
    existing = self._store.get_reservation(order_id)
    if existing is not None and effective_status(existing, now) in (
        ReservationStatus.ACTIVE,
        ReservationStatus.CONFIRMED,
    ):
        raise DuplicateReservationError(order_id)
    for (warehouse, sku), total in totals_by_position(normalized).items():
        free = self._available_at(warehouse, sku, now)
        if total > free:
            raise InsufficientStockError(warehouse, sku, total, free)
    record = ReservationRecord(order_id, normalized, now, now + ttl)
    expires = format_timestamp(record.expires_at)
    self._store.save_reservation(record)
    for line in normalized:
        self._log.append(
            now, "RESERVE", order=order_id, wh=line.warehouse, sku=line.sku, qty=line.qty,
            expires=expires,
        )
    logger.info("reserved %d line(s) for order %s", len(normalized), order_id)
    return snapshot(record, now)

def confirm(self, order_id: str) -> Reservation:
    """Превращает активный резерв в отгрузку: списывает физический остаток."""
    now = self._clock.now()
    record = self._require_reservation(order_id)
    self._require_active(record, now)
    for (warehouse, sku), total in totals_by_position(record.lines).items():
        current = self._store.get_qty(warehouse, sku)
        if total > current:
            raise InsufficientStockError(warehouse, sku, total, current)
    for line in record.lines:
        current = self._store.get_qty(line.warehouse, line.sku)
        self._store.set_qty(line.warehouse, line.sku, current - line.qty)
        self._log.append(
            now, "ISSUE", wh=line.warehouse, sku=line.sku, qty=line.qty, ref=order_id
        )
    record.status = ReservationStatus.CONFIRMED
    self._log.append(now, "RESERVE_CONFIRM", order=order_id)
    logger.info("confirmed reservation for order %s", order_id)
    return snapshot(record, now)

def cancel(self, order_id: str) -> Reservation:
